export const STAGES_PER_ACT = 8;
export const ROOM_COUNT = STAGES_PER_ACT * 3;
export const actIndex = (stage) => Math.floor(stage / STAGES_PER_ACT);
export const roomIndex = (stage) => stage % STAGES_PER_ACT;
export const isBoss = (stage) => roomIndex(stage) === STAGES_PER_ACT - 1;
export const isCamp = (stage) => [2, 5].includes(roomIndex(stage));
export const isElite = (stage) => roomIndex(stage) === 6;
