export const rank = (run, id) => run.upgrades[id] || 0;
export function stats(run) {
  return {
    speed: 90 * (1 + rank(run, "speed") * 0.12),
    damage: 1 + rank(run, "damage") * 0.2,
    fireRate: 1 + rank(run, "rapid") * 0.15,
    echoDamage: 0.6 + rank(run, "echopower") * 0.3,
    echoDuration:
      3.6 + rank(run, "duration") * 1.2 + (run.relic === "spool" ? 1 : 0),
    echoCooldown: 7 / (1 + rank(run, "quickecho") * 0.25),
    echoes: 1 + rank(run, "double"),
    thread: 20 * (1 + rank(run, "thread") * 0.4),
    threadWidth: 3 + rank(run, "wide") * 5,
    burst: 42 * (1 + rank(run, "burst") * 0.25),
    burstRadius: 48 + rank(run, "burst") * 20,
    dashCooldown: 1.5 / (1 + rank(run, "dash") * 0.3),
    pierce: rank(run, "pierce"),
  };
}
